/* ============================================================
   LangLab — Đề thi thử TOEFL iBT
   Do LangLab tự biên soạn theo dạng thức TOEFL iBT (ets.org),
   KHÔNG phải đề thi chính thức của ETS.

   Cấu trúc phần làm trên máy trong app:
     Reading    20 câu · 35 phút · 2 bài đọc học thuật
     Listening  28 câu · 36 phút · 2 hội thoại + 3 bài giảng
     Writing     2 task · 29 phút (Integrated 20′ · Academic Discussion 10′)
   Phần Speaking gồm 4 task nói vào micro — luyện ở màn «Luyện nói».

   Quy đổi: mỗi phần quy về thang 0–30, tổng 0–120 (TOEFL_SCALE).
   ============================================================ */

/* Quy đổi điểm thô sang thang 30 của từng phần (ước lượng theo bảng công bố của ETS) */
const TOEFL_SCALE = {
  reading:   [[20,30],[19,29],[18,28],[17,26],[16,25],[15,23],[14,22],[13,20],[12,18],[11,17],[10,15],[9,13],[8,11],[7,9],[6,7],[5,5],[4,3],[3,2],[2,1]],
  listening: [[28,30],[27,29],[26,28],[25,27],[24,26],[23,25],[22,23],[21,22],[20,21],[19,20],[18,18],[17,17],[16,15],[15,14],[14,13],[13,11],[12,10],[10,7],[8,5],[6,3],[4,1]]
};
function toeflScale(raw, kind){
  const t = TOEFL_SCALE[kind] || TOEFL_SCALE.reading;
  for (let i = 0; i < t.length; i++) if (raw >= t[i][0]) return t[i][1];
  return 0;
}

